const PAYLOAD='';
'use strict';
// Startet die Website aus dem eingebetteten Paket (Testversion).
const fs=require('node:fs'),path=require('node:path'),zlib=require('node:zlib'),os=require('node:os'),cp=require('node:child_process');
const dir=path.join(os.tmpdir(),'yoga-app');
fs.rmSync(dir,{recursive:true,force:true});fs.mkdirSync(dir,{recursive:true});
const tar=zlib.gunzipSync(Buffer.from(PAYLOAD,'base64'));
for(let o=0;o+512<=tar.length;){
  const h=tar.subarray(o,o+512);if(h[0]===0)break;
  const name=h.subarray(0,100).toString().replace(/\0.*$/,'');
  const size=parseInt(h.subarray(124,136).toString().replace(/\0.*$/,'').trim()||'0',8);
  const type=String.fromCharCode(h[156]);o+=512;
  if(type==='0'||type==='\0'){const f=path.join(dir,name);fs.mkdirSync(path.dirname(f),{recursive:true});fs.writeFileSync(f,tar.subarray(o,o+size));}
  o+=Math.ceil(size/512)*512;
}
const run=(a)=>cp.spawnSync(process.execPath,['--disable-warning=ExperimentalWarning',...a],{cwd:dir,stdio:'inherit',env:process.env});
run(['scripts/seed.js']);
const srv=cp.spawn(process.execPath,['--disable-warning=ExperimentalWarning','server.js'],{cwd:dir,stdio:'inherit',env:process.env});
srv.on('exit',(c)=>process.exit(c||0));
['SIGTERM','SIGINT'].forEach((s)=>process.on(s,()=>srv.kill(s)));
